$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$Root = Split-Path -Parent $PSScriptRoot
$Encoded = ""
$TempVerifier = New-TemporaryFile

try {
    $PythonSource = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Encoded))
    Set-Content -Encoding UTF8 -Path $TempVerifier -Value $PythonSource
    python $TempVerifier $Root
}
finally {
    Remove-Item -Force $TempVerifier
}
